const addProcessedToProjectMedia = result => {
  if(!integrated||!result)return;
  const derived=(result.augmentation?.pairs||[]).map(item=>item.augmented_asset_id).filter(Boolean);
  const labeled=(result.labeling?.items||[]).map(item=>item.asset_id).filter(Boolean);
  const assetIds=[...new Set([...derived,...labeled])];
  if(!assetIds.length)return;
  window.parent?.postMessage({type:'alphamotion:add-processed-to-media',run_id:result.run_id,asset_ids:assetIds,labeled_asset_ids:[...new Set(labeled)]},location.origin);
};
