const sendToMotionStudio = () => {
  const assets=state.assets.filter(asset=>state.selected.has(asset.id));
  if(!assets.length)return toast('Select assets to send to Motion Studio');
  window.parent?.postMessage({type:'alphamotion:send-to-motion',asset_ids:assets.map(asset=>asset.id),assets:assets.map(asset=>({id:asset.id,title:asset.title,source:asset.source,folder:asset.folder}))},location.origin);
  toast(`${assets.length} asset${assets.length===1?'':'s'} sent to Motion Studio`);
};
