async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const data=await response.json();if(!response.ok||data.ok===false)throw new Error(data.error||`HTTP ${response.status}`);return data}
const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
const fmtCount=n=>new Intl.NumberFormat('en-US').format(n||0);
function fmtBytes(n){if(!n)return '—';const units=['B','KB','MB','GB','TB'];let i=0,v=n;while(v>=1024&&i<units.length-1){v/=1024;i++}return `${v.toFixed(i?1:0)} ${units[i]}`}
function fmtTime(sec){sec=Math.max(0,sec||0);const m=Math.floor(sec/60),s=Math.floor(sec%60),ms=Math.floor(sec%1*1000);return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(ms).padStart(3,'0')}`}
function initials(name){return name.split(/[\s\/-]/).filter(Boolean).slice(0,2).map(v=>v[0]).join('').toUpperCase()||'?'}
function toast(message){ui.toast.textContent=message;ui.toast.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>ui.toast.hidden=true,2200)}
function escapeHtml(value){const node=document.createElement('span');node.textContent=value??'';return node.innerHTML}
function fmtValue(value,digits=3){if(value===null||value===undefined||value==='')return '—';if(typeof value==='boolean')return value?'Yes':'No';if(typeof value==='number')return Number.isInteger(value)?fmtCount(value):value.toFixed(digits);return String(value)}
function kvRows(entries){return `<dl class="inspector-kv">${entries.map(([key,value])=>`<dt>${escapeHtml(key)}</dt><dd>${escapeHtml(fmtValue(value))}</dd>`).join('')}</dl>`}

