  ui.sourceList.querySelectorAll('[data-source]').forEach(button=>button.onclick=()=>selectSource(button.dataset.source));
  ui.collectionList.innerHTML=state.collections.length?state.collections.map(c=>`<button class="nav-item ${state.collection===c.id?'active':''}" data-collection="${c.id}"><span class="nav-icon">▱</span><span class="nav-copy"><strong>${escapeHtml(c.name)}</strong><small>${fmtCount(c.asset_count)} items</small></span></button>`).join(''):'<span class="nav-copy" style="padding:8px"><small>Drag assets here to organize them</small></span>';
  ui.collectionList.querySelectorAll('[data-collection]').forEach(button=>{button.onclick=()=>selectCollection(button.dataset.collection);button.ondragover=e=>e.preventDefault();button.ondrop=e=>{e.preventDefault();addToCollection(button.dataset.collection,[e.dataTransfer.getData('text/asset-id')].filter(Boolean))}});
