function updateScopeControls(){const inSource=state.libraryMode==='assets'&&Boolean(state.source&&!state.collection&&!state.clusterRun);ui.folderSelect.hidden=!inSource;ui.clusterScopeButton.hidden=!inSource;if(inSource){const sourceAnimated=state.sources.find(item=>item.source===state.source)?.animated||0;const folderInfo=state.folders.find(item=>item.folder===state.folder);const count=state.folder?(folderInfo?.animated||0):sourceAnimated;ui.clusterScopeButton.textContent=state.folder?`Cluster Folder · ${fmtCount(count)}`:`Cluster Source · ${fmtCount(count)}`}}
