async function selectFolder(folder){state.libraryMode='assets';state.folder=folder;state.offset=0;state.assets=[];state.selected.clear();state.selectionAnchorId='';const info=state.folders.find(item=>item.folder===folder);ui.assetTitle.textContent=folder||state.source;ui.catalogEyebrow.textContent=folder?`${state.source} · FOLDER · ${fmtCount(info?.animated||0)} MOTIONS`:'DATA SOURCE';await loadAssets(false);updateScopeControls()}
async function loadAssets(append){const params=new URLSearchParams({status:'ready',limit:'120',offset:String(append?state.offset:0)});if(state.source)params.set('source',state.source);if(state.folder)params.set('folder',state.folder);if(state.collection)params.set('collection',state.collection);if(state.libraryMode==='favorites')params.set('favorites','1');if(state.clusterRun){params.set('cluster_run',state.clusterRun);params.set('cluster_id',state.clusterId)}if(state.query)params.set('q',state.query);const data=await api(`/api/assets?${params}`);state.assets=append?[...state.assets,...data.assets]:data.assets;state.offset=state.assets.length;state.total=data.total;renderAssets()}
async function toggleFavorite(asset){const response=await post('/api/favorites',{asset_id:asset.id,favorite:!asset.favorite});asset.favorite=response.favorite;if(state.current?.id===asset.id){state.current.favorite=response.favorite;renderPreviewFavorite()}if(state.libraryMode==='favorites'&&!response.favorite){state.assets=state.assets.filter(value=>value.id!==asset.id);state.total=Math.max(0,state.total-1)}renderAssets();toast(response.favorite?'Added to Favorites':'Removed from Favorites')}
