function renderAssets(){ui.assetGrid.hidden=false;ui.processHistoryGrid.hidden=true;ui.selectModeButton.hidden=false;ui.assetTotal.textContent=`${fmtCount(state.total)} assets`;ui.browseEmpty.hidden=state.assets.length>0;ui.loadMore.hidden=state.assets.length>=state.total;ui.assetGrid.innerHTML=state.assets.map(a=>`<article class="asset-card ${state.selected.has(a.id)?'selected':''}" data-id="${a.id}" draggable="true"><button class="card-favorite ${a.favorite?'active':''}" data-favorite title="${a.favorite?'Remove from Favorites':'Add to Favorites'}" aria-label="${a.favorite?'Remove from Favorites':'Add to Favorites'}">${a.favorite?'★':'☆'}</button><input class="card-check" type="checkbox" aria-label="Select ${escapeHtml(a.title)}" ${state.selectMode?'':'hidden'} ${state.selected.has(a.id)?'checked':''}><span class="format">${escapeHtml(a.format.toUpperCase())}</span><h3 title="${escapeHtml(a.title)}">${escapeHtml(a.title)}</h3><p>${escapeHtml(a.folder||a.source)}</p><div class="card-foot"><span>${fmtBytes(a.size)}</span><span class="${a.animated?'animated-dot':''}">${a.animated?'● Motion':'Static'}</span></div></article>`).join('');
  ui.assetGrid.querySelectorAll('.asset-card').forEach(card=>{const asset=state.assets.find(a=>a.id===card.dataset.id);card.querySelector('[data-favorite]').onclick=event=>{event.preventDefault();event.stopPropagation();toggleFavorite(asset)};card.ondragstart=e=>e.dataTransfer.setData('text/asset-id',asset.id);card.onclick=e=>{const selecting=state.selectMode||e.target.matches('input')||e.shiftKey||e.ctrlKey||e.metaKey;if(selecting){selectAssetWithModifiers(asset.id,e);return}openPreview(asset)};});updateSelectionBar()}
function selectAssetWithModifiers(id,event){
  const index=state.assets.findIndex(asset=>asset.id===id);
  const anchor=state.assets.findIndex(asset=>asset.id===state.selectionAnchorId);
  state.selectMode=true;
  ui.selectModeButton.textContent='Done';
  if(event.shiftKey&&anchor>=0&&index>=0){
    for(let cursor=Math.min(anchor,index);cursor<=Math.max(anchor,index);cursor++)state.selected.add(state.assets[cursor].id);
  }else{
    state.selected.has(id)?state.selected.delete(id):state.selected.add(id);
    state.selectionAnchorId=id;
  }
  renderAssets();
}
function updateSelectionBar(){ui.selectionBar.hidden=state.selected.size===0;ui.selectionCount.textContent=`${state.selected.size} selected`}

