async function openInspector(){if(!state.current)return;ui.adjustDrawer.hidden=true;ui.inspectorDrawer.hidden=false;ui.inspectorLoading.hidden=Boolean(state.inspection);setTimeout(resize);if(state.inspection){renderInspector();return}try{const response=await api(`/api/inspect?id=${encodeURIComponent(state.current.id)}`);if(state.current?.id!==response.inspection?.summary?.asset_id)return;state.inspection=response.inspection;state.sceneInventory=collectSceneInventory();renderInspector()}catch(error){ui.inspectorLoading.textContent=error.message}}
function selectInspectorTab(tab){state.inspectorTab=tab;if(state.jointMarker&&tab!=='skeleton')state.jointMarker.visible=false;document.querySelectorAll('[data-inspector-tab]').forEach(button=>button.classList.toggle('active',button.dataset.inspectorTab===tab));document.querySelectorAll('[data-inspector-panel]').forEach(panel=>panel.hidden=panel.dataset.inspectorPanel!==tab)}
