function setLoading(on,title='',detail=''){ui.loadingOverlay.hidden=!on;if(title)ui.loadingText.textContent=title;if(detail)ui.loadingDetail.textContent=detail}
function showError(message){ui.errorText.textContent=message;ui.errorOverlay.hidden=false}function hideError(){ui.errorOverlay.hidden=true}
function disposeObject(object){object?.traverse(node=>{node.geometry?.dispose?.();if(node.material){(Array.isArray(node.material)?node.material:[node.material]).forEach(m=>m.dispose?.())}})}
function clearViewer(){if(state.root){scene.remove(state.root);disposeObject(state.root)}if(state.skeletonHelper){scene.remove(state.skeletonHelper);state.skeletonHelper.geometry?.dispose?.();state.skeletonHelper.material?.dispose?.()}if(state.jointMarker)state.jointMarker.visible=false;state.root=new THREE.Group();scene.add(state.root);state.mixer=null;state.clip=null;state.skeletonHelper=null;state.skeletonData=null;state.skeletonPoints=null;state.skeletonLines=null;state.contactMarkers=[];state.time=0;state.duration=0;state.playing=false;ui.motionWarningTrack.hidden=true;ui.motionWarningTrack.innerHTML='';setTransport(0,false,'Static asset')}
async function loadPreview(preview){let object=null,animations=[];const quality=preview.preview_metadata||{};const sourceFps=quality.source_fps??quality.fps??preview.source_fps??preview.fps;if(sourceFps)setPreviewFps(sourceFps);if(quality.quality_warning){ui.qualityBadge.textContent=`Source quality warning: ${quality.arm_rotation_spikes_over_60deg} wrist/elbow steps exceed 60° (maximum ${Number(quality.max_arm_rotation_step_degrees).toFixed(1)}°)`;ui.qualityBadge.hidden=false}if(preview.model_url){({object,animations}=await loadModel(preview));state.root.add(object);const hasBones=addEmbeddedSkeleton(object);setupAnimations(object,animations);if(preview.skeleton_url&&!hasBones)await loadSkeleton(preview.skeleton_url)}else if(preview.viewer==='bvh'){await loadBVH(preview.model_url)}else if(preview.skeleton_url){await loadSkeleton(preview.skeleton_url)}else throw new Error('Decoder returned no displayable content');applyRecipe();fitCamera()}
