async function loadBVH(url){const data=await new BVHLoader().loadAsync(url);state.root.add(data.skeleton.bones[0]);state.skeletonHelper=new THREE.SkeletonHelper(data.skeleton.bones[0]);scene.add(state.skeletonHelper);setupAnimations(data.skeleton.bones[0],[data.clip])}
async function loadSkeleton(url){const data=await (await fetch(url)).json();state.skeletonData=data;if(data.fps)setPreviewFps(data.fps);const count=data.joint_count;const positions=new Float32Array(count*3);const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));const pointMaterial=new THREE.PointsMaterial({color:0xffa263,size:.025,sizeAttenuation:true,depthTest:false});state.skeletonPoints=new THREE.Points(geometry,pointMaterial);const segments=[];data.parents.forEach((p,i)=>{if(p>=0)segments.push(p,i)});const lineGeometry=new THREE.BufferGeometry();lineGeometry.setAttribute('position',new THREE.BufferAttribute(new Float32Array(segments.length*3),3));state.skeletonLines={object:new THREE.LineSegments(lineGeometry,new THREE.LineBasicMaterial({color:0xf3c3a0,depthTest:false,transparent:true,opacity:.9})),segments};state.root.add(state.skeletonPoints,state.skeletonLines.object);state.duration=Math.max(0,(data.frame_count-1)/(data.fps||30));updateSkeleton(0);setTransport(state.duration,data.frame_count>1,`${fmtCount(data.frame_count)} frames · ${data.fps||30} FPS`)}
