function setTransport(duration,enabled,label){ui.timeline.disabled=!enabled;ui.playButton.disabled=!enabled;ui.speedSelect.disabled=!enabled;ui.durationTime.textContent=fmtTime(duration);ui.clipInfo.textContent=label;ui.playButton.textContent='▶';updateTransportUI()}
function updateTransportUI(){ui.timeline.value=state.duration?Math.round(state.time/state.duration*1000):0;ui.currentTime.textContent=fmtTime(state.time);updateContactUI()}
