async function loadRecipe(id){try{const data=await api(`/api/recipe?id=${id}`);state.folderRecipe=data.folder_recipe||{};const base={...defaultRecipe(),...state.folderRecipe};state.assetRecipe=Object.fromEntries(Object.entries(data.asset_recipe||{}).filter(([key,value])=>value!==base[key]));state.recipeScope='asset';state.recipe={...base,...state.assetRecipe};ui.recipeScope.value='asset';ui.recipeScopeNote.textContent=`Asset settings override the defaults for “${data.folder||'Root'}”.`}catch{state.folderRecipe={};state.assetRecipe={};state.recipe=defaultRecipe()}syncRecipeUI()}
function displayedRecipe(){return state.recipeScope==='folder'?{...defaultRecipe(),...state.folderRecipe}:{...defaultRecipe(),...state.folderRecipe,...state.assetRecipe}}
function syncRecipeUI(){state.recipe=displayedRecipe();const r=state.recipe;ui.upAxis.value=r.upAxis;ui.rotateX.value=r.rotateX;ui.rotateY.value=r.rotateY;ui.rotateZ.value=r.rotateZ;ui.displayScale.value=r.scale;ui.mirrorX.checked=r.mirrorX;ui.mirrorY.checked=r.mirrorY;ui.mirrorZ.checked=r.mirrorZ;ui.swapLR.checked=r.swapLR;ui.groundAsset.checked=r.ground;applyRecipe()}
function recipeFromUI(){return {upAxis:ui.upAxis.value,rotateX:Number(ui.rotateX.value)||0,rotateY:Number(ui.rotateY.value)||0,rotateZ:Number(ui.rotateZ.value)||0,scale:Math.max(.0001,Number(ui.displayScale.value)||1),mirrorX:ui.mirrorX.checked,mirrorY:ui.mirrorY.checked,mirrorZ:ui.mirrorZ.checked,swapLR:ui.swapLR.checked,ground:ui.groundAsset.checked}}
