const augmentationCheckLabels={finite_numeric_values:'Finite numeric values',output_frame_count:'Expected output frame count',duration_scale_within_tolerance:'Duration multiplier within tolerance',rotation_endpoints_exact:'Rotation endpoints preserved',translation_endpoints_exact:'Translation endpoints preserved',shape_parameters_unchanged:'Body shape unchanged',roundtrip_rotation_p95_below_0_5deg:'Round-trip rotation P95 < 0.5°',roundtrip_rotation_p99_below_1deg:'Round-trip rotation P99 < 1°',roundtrip_rotation_outlier_rate_below_1pct:'Round-trip outliers < 1%',roundtrip_rotation_max_below_2deg:'Legacy maximum error < 2°',roundtrip_translation_rms_below_1mm:'Round-trip translation RMS < 1 mm',output_rotation_step_p99_not_increased:'Rotation step P99 not increased',output_rotation_step_max_not_increased:'Maximum rotation step not increased',output_translation_steps_not_increased:'Translation steps not increased',phase_order_preserved_by_monotonic_mapping:'Motion phase order preserved',source_and_target_fps_equal:'Source and output FPS match'};
Object.assign(augmentationCheckLabels,{identity_multiplier_is_elementwise_exact:'m = 1.0 is elementwise exact',rotation_endpoints_preserved:'Rotation endpoints preserved',translation_endpoints_preserved:'Translation endpoints preserved',rotation_matrices_orthogonal:'Rotation matrices are orthogonal',rotation_determinants_positive_one:'det(R) = +1',aliasing_limit_respected:'PSD-derived anti-alias limit respected',normalized_high_frequency_energy_not_increased:'No normalized high-frequency energy increase',normalized_angular_acceleration_distance_acceptable:'Angular acceleration distribution preserved',foot_slide_not_significantly_increased:'Foot slide not significantly increased'});
Object.assign(augmentationCheckLabels,{poses_unchanged:'Joint rotations unchanged',frame_count_unchanged:'Frame count unchanged',source_fps_preserved:'Source FPS preserved',betas_constant_over_clip:'One body shape per clip',human_shape_bounds_respected:'Human shape bounds respected',requested_proportions_reached:'Sampled proportions reached',source_contacts_preserved:'Source foot contacts preserved',contact_geometry_consistent:'Contact sole stays near source support point'});
function renderAugmentationWorkspace(){const result=state.augmentationResult;if(!result?.pairs?.length)return;const pair=result.pairs[state.augmentationPair]||result.pairs[0];const validation=pair.validation||{};const metrics=validation.metrics||{};const scale=Number(pair.duration_scale||metrics.requested_duration_scale||1.15);const roundtripP99=metrics.roundtrip_rotation_p99_degrees??metrics.roundtrip_rotation_p95_degrees??0;ui.augmentationRunSummary.textContent=`${fmtCount(result.pairs.length)} derived file${result.pairs.length===1?'':'s'} · Run ${result.run_id}`;ui.augmentationMethod.textContent=result.params?.method||'Uniform duration scaling';ui.augmentationJson.href=result.result_json_url;ui.augmentationPairList.innerHTML=result.pairs.map((item,index)=>{const itemScale=Number(item.duration_scale||item.validation?.metrics?.requested_duration_scale||1.15);return `<button class="augmentation-pair ${index===state.augmentationPair?'active':''}" data-augmentation-pair="${index}"><i></i><span><strong>${escapeHtml(item.original?.title||item.original_asset_id)}</strong><small>Duration ×${itemScale.toFixed(2)} · ${escapeHtml(item.augmented_filename)}</small></span><span>${item.validation?.passed?'PASS':'FAIL'}</span></button>`}).join('');ui.augmentationPairList.querySelectorAll('[data-augmentation-pair]').forEach(button=>button.onclick=()=>{state.augmentationPair=Number(button.dataset.augmentationPair);renderAugmentationWorkspace()});ui.augmentationPairIndex.textContent=`PAIR ${state.augmentationPair+1} / ${result.pairs.length}`;ui.augmentationPairTitle.textContent=pair.original?.title||pair.original_asset_id;ui.augmentationValidationState.textContent=validation.passed?'✓ VALIDATED':'✕ VALIDATION FAILED';ui.augmentationValidationState.classList.toggle('failed',!validation.passed);ui.augmentationOriginalName.textContent=`${pair.original?.title||'Original motion'}.${pair.original?.format||'npz'}`;ui.augmentationOriginalMeta.textContent=`${fmtCount(metrics.source_frames)} frames · ${Number(metrics.source_duration_seconds||0).toFixed(3)} s`;ui.augmentationDerivedName.textContent=pair.augmented_filename;ui.augmentationDerivedMeta.textContent=`${fmtCount(metrics.output_frames)} frames · ${Number(metrics.output_duration_seconds||0).toFixed(3)} s · duration ×${scale.toFixed(3)}`;ui.augmentationMetrics.innerHTML=`<div class="validation-metric"><small>Round-trip P99</small><strong>${Number(roundtripP99).toFixed(4)}°</strong></div><div class="validation-metric"><small>Rotation step max</small><strong>${Number(metrics.source_rotation_step_max_degrees||0).toFixed(2)}° → ${Number(metrics.output_rotation_step_max_degrees||0).toFixed(2)}°</strong></div><div class="validation-metric"><small>Root RMS</small><strong>${(Number(metrics.roundtrip_translation_rms_meters||0)*1000).toFixed(4)} mm</strong></div><div class="validation-metric"><small>Outliers > 2°</small><strong>${(Number(metrics.roundtrip_rotation_outlier_rate_over_2deg||0)*100).toFixed(3)}%</strong></div>`;ui.augmentationWarnings.innerHTML=(validation.warnings||[]).map(warning=>`<div>⚠ ${escapeHtml(warning)}</div>`).join('');ui.augmentationWarnings.hidden=!(validation.warnings||[]).length;ui.augmentationChecks.innerHTML=Object.entries(validation.checks||{}).map(([key,passed])=>`<span class="validation-check ${passed?'':'failed'}">${passed?'✓':'✕'} ${escapeHtml(augmentationCheckLabels[key]||key)}</span>`).join('');comparisonViewer.loadPair(pair.original,pair.augmented).catch(error=>toast(error.message))}

function augmentationGroups(result){
  const groups=new Map();
  result.pairs.forEach((pair,index)=>{
    const key=pair.original_asset_id||pair.original?.id;
    if(!groups.has(key))groups.set(key,{key,original:pair.original,firstPair:index,pairs:[]});
    groups.get(key).pairs.push({pair,index});
  });
  return [...groups.values()];
}

function augmentationEntry(result,key){
  if(key.startsWith('a:')){
    const pairIndex=Number(key.slice(2));
    const pair=result.pairs[pairIndex];
    if(!pair)return null;
    return {key,role:'augmented',pairIndex,asset:pair.augmented,pair,runId:result.run_id};
  }
  const originalId=key.slice(2);
  const pairIndex=result.pairs.findIndex(pair=>(pair.original_asset_id||pair.original?.id)===originalId);
  const pair=result.pairs[pairIndex];
  if(!pair)return null;
  return {key,role:'original',pairIndex,asset:pair.original,pair,runId:result.run_id};
}

function renderAugmentationSidebar(result){
  const slotKeys=new Set(state.augmentationSlots.filter(Boolean).map(entry=>entry.key));
  ui.augmentationPairList.innerHTML=augmentationGroups(result).map(group=>{
    const originalKey=`o:${group.key}`;
    const originalSelected=slotKeys.has(originalKey)?'in-compare':'';
    const expanded=state.augmentationExpandedSources.has(group.key);
    const variants=group.pairs.map(({pair,index})=>{
      const key=`a:${index}`;
      const scale=Number(pair.duration_scale||pair.validation?.metrics?.requested_duration_scale||1.15);
      const active=index===state.augmentationPair?'active-validation':'';
      const selected=slotKeys.has(key)?'in-compare':'';
      return `<button class="augmentation-tree-row augmentation-variant-row ${active} ${selected}" data-augmentation-entry="${key}" draggable="true"><i></i><span><small>AUGMENTED</small><strong>${escapeHtml(pair.augmented_filename)}</strong><small>Time · duration ×${scale.toFixed(2)}</small></span><em>${pair.validation?.passed?'PASS':'FAIL'}</em></button>`;
    }).join('');
    return `<section class="augmentation-tree-group ${expanded?'expanded':''}"><button class="augmentation-tree-row augmentation-original-row ${originalSelected}" data-augmentation-entry="${originalKey}" data-augmentation-source="${escapeHtml(group.key)}" draggable="true" aria-expanded="${expanded}"><i></i><span><small>ORIGINAL</small><strong>${escapeHtml(group.original?.title||group.key)}</strong></span><em><b>${escapeHtml((group.original?.format||'npz').toUpperCase())}</b><span class="augmentation-caret">›</span></em></button><div class="augmentation-variant-list" ${expanded?'':'hidden'}>${variants}</div></section>`;
  }).join('');
  ui.augmentationPairList.querySelectorAll('[data-augmentation-entry]').forEach(row=>{
    const key=row.dataset.augmentationEntry;
    row.onclick=()=>{
      if(row.dataset.augmentationSource){
        const sourceKey=row.dataset.augmentationSource;
        state.augmentationExpandedSources.has(sourceKey)?state.augmentationExpandedSources.delete(sourceKey):state.augmentationExpandedSources.add(sourceKey);
        renderAugmentationSidebar(result);
        return;
      }
      const entry=augmentationEntry(result,key);
      if(entry)loadAugmentationSlot(entry.role==='original'?0:1,entry);
    };
    row.ondragstart=event=>{
      event.dataTransfer.effectAllowed='copy';
      event.dataTransfer.setData('application/x-bodydata-motion',key);
      event.dataTransfer.setData('text/plain',key);
      row.classList.add('dragging');
    };
    row.ondragend=()=>row.classList.remove('dragging');
    row.onpointerdown=event=>{
      const start={x:event.clientX,y:event.clientY};
      const finish=upEvent=>{
        if(Math.hypot(upEvent.clientX-start.x,upEvent.clientY-start.y)<12)return;
        const panel=document.elementFromPoint(upEvent.clientX,upEvent.clientY)?.closest('[data-compare-slot]');
        const entry=augmentationEntry(result,key);
        if(panel&&entry)loadAugmentationSlot(Number(panel.dataset.compareSlot),entry);
      };
      document.addEventListener('pointerup',finish,{once:true});
    };
  });
}

function updateAugmentationPanel(slot,entry){
  const pair=entry.pair;
  const metrics=pair.validation?.metrics||{};
  const requestedScale=Number(pair.duration_scale||metrics.requested_duration_scale||1.15);
  const actualScale=Number(pair.actual_duration_scale||metrics.measured_duration_scale||requestedScale);
  const isLeft=slot===0;
  const panel=isLeft?ui.originalComparePanel:ui.derivedComparePanel;
  const role=isLeft?ui.compareOriginalRole:ui.compareDerivedRole;
  const name=isLeft?ui.augmentationOriginalName:ui.augmentationDerivedName;
  const meta=isLeft?ui.augmentationOriginalMeta:ui.augmentationDerivedMeta;
  panel.dataset.contentRole=entry.role;
  role.textContent=entry.role==='original'?'ORIGINAL':'AUGMENTED · TIME';
  name.textContent=entry.role==='original'?`${entry.asset?.title||'Original motion'}.${entry.asset?.format||'npz'}`:(pair.augmented_filename||`${entry.asset?.title}.${entry.asset?.format||'npz'}`);
  meta.textContent=entry.role==='original'
    ?`${fmtCount(metrics.source_frames)} frames · ${Number(metrics.source_duration_seconds||0).toFixed(3)} s · ${Number(metrics.source_fps||0).toFixed(2)} FPS`
    :`${fmtCount(metrics.output_frames)} frames · ${Number(metrics.output_duration_seconds||0).toFixed(3)} s · ${Number(metrics.output_fps||0).toFixed(2)} FPS · requested ×${requestedScale.toFixed(3)} · actual ×${actualScale.toFixed(3)}`;
}

function renderAugmentationValidation(result){
  const pair=result.pairs[state.augmentationPair]||result.pairs[0];
  const validation=pair.validation||{};
  const metrics=validation.metrics||{};
  ui.augmentationPairIndex.textContent=`VALIDATION ${state.augmentationPair+1} / ${result.pairs.length}`;
  ui.augmentationPairTitle.textContent=pair.augmented_filename||pair.original?.title||pair.original_asset_id;
  ui.augmentationValidationState.textContent=validation.passed?'VALIDATED':'VALIDATION FAILED';
  ui.augmentationValidationState.classList.toggle('failed',!validation.passed);
  ui.augmentationMetrics.innerHTML=`<div class="validation-metric"><small>Measured motion bandwidth</small><strong>${Number(metrics.motion_bandwidth_hz_99pct||0).toFixed(3)} Hz</strong></div><div class="validation-metric"><small>Frame rate preserved</small><strong>${Number(metrics.source_fps||0).toFixed(2)} → ${Number(metrics.output_fps||0).toFixed(2)} FPS</strong></div><div class="validation-metric"><small>Angular acceleration distance</small><strong>${Number(metrics.angular_acceleration_wasserstein_normalized||0).toFixed(4)}</strong></div><div class="validation-metric"><small>Normalized high-frequency energy</small><strong>${(Number(metrics.source_high_frequency_energy_ratio||0)*100).toFixed(2)}% → ${(Number(metrics.output_high_frequency_energy_ratio||0)*100).toFixed(2)}%</strong></div>`;
  ui.augmentationWarnings.innerHTML=(validation.warnings||[]).map(warning=>`<div>${escapeHtml(warning)}</div>`).join('');
  ui.augmentationWarnings.hidden=!(validation.warnings||[]).length;
  ui.augmentationChecks.innerHTML=Object.entries(validation.checks||{}).map(([key,passed])=>`<span class="validation-check ${passed?'':'failed'}">${passed?'PASS':'FAIL'} · ${escapeHtml(augmentationCheckLabels[key]||key)}</span>`).join('');
  ui.augmentationQualityPlot.hidden=!pair.quality_plot_url;
  if(pair.quality_plot_url)ui.augmentationQualityPlot.href=pair.quality_plot_url;
}

function loadAugmentationSlot(slot,entry){
  state.augmentationSlots[slot]=entry;
  state.augmentationPair=entry.pairIndex;
  updateAugmentationPanel(slot,entry);
  renderAugmentationValidation(state.augmentationResult);
  renderAugmentationSidebar(state.augmentationResult);
  comparisonViewer.loadSlot(slot,entry.asset).catch(error=>toast(error.message));
}

function bindAugmentationDropTargets(result){
  [ui.originalComparePanel,ui.derivedComparePanel].forEach((panel,slot)=>{
    panel.ondragover=event=>{event.preventDefault();event.dataTransfer.dropEffect='copy';panel.classList.add('drag-over')};
    panel.ondragleave=event=>{if(!panel.contains(event.relatedTarget))panel.classList.remove('drag-over')};
    panel.ondrop=event=>{
      event.preventDefault();
      panel.classList.remove('drag-over');
      const key=event.dataTransfer.getData('application/x-bodydata-motion')||event.dataTransfer.getData('text/plain');
      const entry=augmentationEntry(result,key);
      if(entry)loadAugmentationSlot(slot,entry);
    };
  });
}

function renderAugmentationWorkspaceV2(){
  const result=state.augmentationResult;
  if(!result?.pairs?.length)return;
  if(state.augmentationSlots.some(entry=>!entry||entry.runId!==result.run_id)){
    state.augmentationSlots=[augmentationEntry(result,`o:${result.pairs[0].original_asset_id||result.pairs[0].original?.id}`),augmentationEntry(result,'a:0')];
    state.augmentationPair=0;
    state.augmentationExpandedSources.clear();
  }
  ui.augmentationRunSummary.textContent=`${fmtCount(result.pairs.length)} derived file${result.pairs.length===1?'':'s'} · ${fmtCount(augmentationGroups(result).length)} original${augmentationGroups(result).length===1?'':'s'} · Run ${result.run_id}`;
  ui.augmentationMethod.textContent=result.params?.method||'Uniform duration scaling';
  ui.augmentationJson.href=result.result_json_url;
  ui.augmentationSaveState.textContent=result.saved?'SAVED':'CACHED DRAFT';
  ui.augmentationSaveState.classList.toggle('saved',Boolean(result.saved));
  ui.saveAugmentationButton.textContent=result.saved?'Saved':'Save';
  ui.saveAugmentationButton.disabled=Boolean(result.saved);
  renderAugmentationSidebar(result);
  renderAugmentationValidation(result);
  state.augmentationSlots.forEach((entry,slot)=>updateAugmentationPanel(slot,entry));
  bindAugmentationDropTargets(result);
  comparisonViewer.loadPair(state.augmentationSlots[0].asset,state.augmentationSlots[1].asset).catch(error=>toast(error.message));
}

renderAugmentationWorkspace=renderAugmentationWorkspaceV2;

async function saveCurrentAugmentation(){
  const result=state.augmentationResult;
  if(!result||result.saved)return;
  ui.saveAugmentationButton.disabled=true;ui.saveAugmentationButton.textContent='Saving…';
  try{
    const response=await post('/api/augmentation-save',{run_id:result.run_id});
    state.augmentationResult=response.result;
    renderAugmentationWorkspace();
    await Promise.all([refreshStatus(),loadSources()]);
    toast(`Saved ${response.result.pairs.length} augmented file${response.result.pairs.length===1?'':'s'} to the Library`);
  }catch(error){ui.saveAugmentationButton.disabled=false;ui.saveAugmentationButton.textContent='Save';toast(`Save failed: ${error.message}`)}
}

