async function init(){if(integrated){localStorage.setItem('bodydata-tour-complete','1');document.body.classList.add('integrated')}const theme=integrated?'dark':(localStorage.getItem('bodydata-theme')||'light');document.body.dataset.theme=theme;scene.background=new THREE.Color(theme==='dark'?0x090c10:0xeaebe8);comparisonViewer.setTheme();resultsViewer.setTheme();await Promise.all([refreshStatus(),loadSources(),loadCollections()]);await loadAssets(false);const savedClusterRun=location.hash.startsWith('#cluster=')?decodeURIComponent(location.hash.slice(9)):'';const savedAugmentationRun=location.hash.startsWith('#augmentation=')?decodeURIComponent(location.hash.slice(14)):'';const savedProcessRun=location.hash.startsWith('#process=')?decodeURIComponent(location.hash.slice(9)):'';if(savedClusterRun){try{const loaded=await api(`/api/cluster?run=${encodeURIComponent(savedClusterRun)}`);openAnalysisWorkspace(loaded.result)}catch(error){history.replaceState(null,'',location.pathname);toast(`Could not restore cluster result: ${error.message}`)}}else if(savedAugmentationRun){try{const loaded=await api(`/api/augment?run=${encodeURIComponent(savedAugmentationRun)}`);openAugmentationWorkspace(loaded.result)}catch(error){history.replaceState(null,'',location.pathname);toast(`Could not restore augmentation result: ${error.message}`)}}else if(savedProcessRun){try{const loaded=await api(`/api/process?run=${encodeURIComponent(savedProcessRun)}`);openProcessResult(loaded.result)}catch(error){history.replaceState(null,'',location.pathname);toast(`Could not restore processing result: ${error.message}`)}}if(localStorage.getItem('bodydata-tour-complete')!=='1')setTimeout(showInitialTourWelcome,450);requestAnimationFrame(animate);setInterval(refreshStatus,12000)}
addEventListener('message',async event=>{if(event.origin!==location.origin)return;const type=event.data?.type;if(type!=='alphamotion:open-process'&&type!=='alphamotion:open-project-preview')return;const ids=type==='alphamotion:open-project-preview'?[event.data.asset_id]:(event.data.asset_ids||[]).filter(Boolean);if(!ids.length)return;try{const response=await api(`/api/assets?status=ready&limit=500&ids=${encodeURIComponent(ids.join(','))}`);if(!response.assets.length)throw new Error('No matching Data Studio assets');if(type==='alphamotion:open-project-preview')openProjectMotionResult(response.assets[0],Boolean(event.data.show_contacts));else openProcess(response.assets)}catch(error){toast(`Could not open Motion Studio selection: ${error.message}`)}});
